import{_ as a,o as t,c as o,a7 as i}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Office Pulse Data Collection","description":"Official data-collection information for Office Pulse.","frontmatter":{"title":"Office Pulse Data Collection","description":"Official data-collection information for Office Pulse.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/office-pulse.md","filePath":"data-collection/office-pulse.md"}'),l={name:"data-collection/office-pulse.md"};function r(s,e,c,n,d,f){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="office-pulse-data-collection" tabindex="-1">Office Pulse Data Collection <a class="header-anchor" href="#office-pulse-data-collection" aria-label="Permalink to &quot;Office Pulse Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 1, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>Office Pulse stores attendance state, settings, tasks, checklists, stopwatch state, memos, cue cards, file-view history, ticket overrides, caches, reminder state, and security settings in localStorage. General app records are not encrypted. PIN verification uses a salted PBKDF2 verifier, and Android handles biometric verification without giving the app biometric templates.</p><h2 id="google-processing" tabindex="-1">Google processing <a class="header-anchor" href="#google-processing" aria-label="Permalink to &quot;Google processing&quot;">​</a></h2><p>The app reads configured Google Sheets and submits user-approved fields to configured Google Forms. Google and the sheet or form owner can receive the requested identifiers, submitted workplace or productivity information, and standard connection metadata.</p><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>Office Pulse has no developer-operated advertising, analytics, or telemetry service. The developer does not automatically receive local device records. Form submissions or sheet rows are available to their configured owners.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',10)])])}const u=a(l,[["render",r]]);export{h as __pageData,u as default};
